def flood(seed_pred, nbr):
    seen=[[False]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in range(W):
            if inp[r][c]==1 and seed_pred(r,c): seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for x,y in nbr(r,c):
            if not seen[x][y]: seen[x][y]=True; q.append((x,y))
    return [[3 if seen[r][c] else inp[r][c] for c in range(W)] for r in range(H)]
